package com.nightbeam.donutshards.reward;
import com.nightbeam.donutshards.model.*;import com.nightbeam.donutshards.scheduler.*;import com.nightbeam.donutshards.service.MessageService;import com.nightbeam.donutshards.transaction.TransactionService;import org.bukkit.GameMode;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;
public final class RewardService implements Listener {private final TransactionService tx;private final SchedulerService scheduler;private final MessageService messages;private final Map<UUID,Player> online=new ConcurrentHashMap<>();private final AtomicLong generation=new AtomicLong();private volatile TaskHandle task;public RewardService(TransactionService tx,SchedulerService scheduler,MessageService messages){this.tx=tx;this.scheduler=scheduler;this.messages=messages;}
 public void start(){var current=generation.incrementAndGet();var old=task;if(old!=null)old.cancel();task=scheduler.asyncRepeating(()->{if(generation.get()!=current)return;for(var entry:online.entrySet()){var p=entry.getValue();scheduler.entity(p,()->check(p),()->online.remove(entry.getKey()));}},java.time.Duration.ofSeconds(60),java.time.Duration.ofSeconds(60));}
 private void check(Player p){if(p.isDead()||p.getGameMode()==GameMode.SPECTATOR||p.isInsideVehicle())return;var context=new MutationContext(TransactionType.REWARD,"reward:sugar-orbit",null,"reward:"+p.getUniqueId()+':'+(System.currentTimeMillis()/60000),Map.of("reward","sugar-orbit"));tx.add(p.getUniqueId(),1,context).whenComplete((r,e)->scheduler.entity(p,()->{if(e==null&&r.success()){p.sendActionBar(messages.render("<gradient:#ffd166:#ff78b8>+1 Shard</gradient>",Map.of()));p.playSound(p.getLocation(),org.bukkit.Sound.ENTITY_EXPERIENCE_ORB_PICKUP,0.7f,1.3f);}},()->{}));}
 @EventHandler public void join(PlayerJoinEvent e){online.put(e.getPlayer().getUniqueId(),e.getPlayer());}
 @EventHandler public void quit(PlayerQuitEvent e){online.remove(e.getPlayer().getUniqueId());tx.forget(e.getPlayer().getUniqueId());}
 public void stop(){generation.incrementAndGet();if(task!=null)task.cancel();online.clear();}}
